def cycle_basis(grid):
 verts={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1};adj={v:[] for v in verts}
 for r,c in verts:
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   q=(r+dr,c+dc)
   if q in verts:adj[(r,c)].append(q)
 parent={}; tree=set(); non=[]
 for root in verts:
  if root in parent:continue
  parent[root]=None;stack=[root]
  while stack:
   v=stack.pop()
   for u in adj[v]:
    e=frozenset((v,u))
    if u not in parent: parent[u]=v;tree.add(e);stack.append(u)
    elif e not in tree and e not in non: non.append(e)
 # fundamental cycles paths in tree
 cycles=[]
 for e in non:
  a,b=tuple(e)
  aa=[];x=a
  while x is not None:aa.append(x);x=parent[x]
  bb=[];x=b
  while x is not None:bb.append(x);x=parent[x]
  common=next(x for x in aa if x in set(bb)); cyc=aa[:aa.index(common)+1]+list(reversed(bb[:bb.index(common)]))
  cycles.append(cyc)
 return cycles
