source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    enclosed = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            touches = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                touches |= y == 0 or x == 0 or y == h - 1 or x == w - 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            if not touches:
                enclosed.append(comp)
    active = set()
    interior = set()
    for comp in enclosed:
        interior.update(comp)
        for y, x in comp:
            if any(0 <= y + dy < h and 0 <= x + dx < w and grid[y + dy][x + dx] == 1
                   for dy in (-1, 0, 1) for dx in (-1, 0, 1) if dy or dx):
                out[y][x] = 3
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                p = (y + dy, x + dx)
                if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 1:
                    active.add(p)
    todo = list(active)
    while todo:
        y, x = todo.pop()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (y + dy, x + dx)
            if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 1 and p not in active:
                active.add(p)
                todo.append(p)
    for y, x in active:
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                yy, xx = y + dy, x + dx
                if 0 <= yy < h and 0 <= xx < w and out[yy][xx] == 0 and (yy, xx) not in interior:
                    out[yy][xx] = 2
    unseen = set(active)
    while unseen:
        seed = unseen.pop()
        comp = {seed}
        q = [seed]
        while q:
            y, x = q.pop()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                p = (y + dy, x + dx)
                if p in unseen:
                    unseen.remove(p)
                    comp.add(p)
                    q.append(p)
        y = min(a for a, b in comp) - 1
        x = min(b for a, b in comp) - 1
        if 0 <= y < h and 0 <= x < w and out[y][x] == 0 and (y, x) not in interior:
            out[y][x] = 2
